def min_cost(n, m, strings, changes):
    import heapq
    from collections import defaultdict
    dp = defaultdict(list)
    min_cost = float('inf')

    for i in range(n):
        for ltr in range(26):
            count = sum((letters[ltr] == changes[i][ltr]) for letters in changes[i])
            dp[count].append(i)

    for count in dp:
        if count % 2 == 0:
            heapq.heapify(dp[count])
        else:
            heapq.heappush(dp[count], float('inf'))
        while dp[count][-1] + 1 == dp[count][0]:
            heapq.heappop(dp[count])
        while dp[count] and dp[count][0] > dp[(count + 1) // 2]:
            heapq.heappop(dp[count])
            heapq.heappush(dp[count], dp[(count + 1) // 2])
        if dp[count]:
            min_cost = min(min_cost, dp[count][0])

    return min_cost

