            cur_color = colors[j]

            if prev_color == cur_color:
                continue

            if cur_color == 'R':
                blue_edges += 1
            else:
                red_neighbours += 1

            if prev_color == 'B' and cur_color == 'G':
                blue_edges += 1
            elif prev_color == 'R' and cur_color == 'G':
                red_neighbours += 1

            if (blue_edges == 1 and red_neighbours >= 2) or (red_neighbours == 1 and blue_edges >= 2):
                return "Yes"
        prev_color = colors[i]

    return "No"

