import collections
from typing import List

def maximize_weight(tents: List[List[int]]) -> int:
    x_positions = [tent[0] for tent in tents]
    y_positions = [tent[1] for tent in tents]
    important_tents_count = {}

    for x, y in x_positions + y_positions:
        if x % 2 == 0 and y % 2 == 0:
            if x in important_tents_count:
                important_tents_count[x].append((y, y))
            else:
                important_tents_count[x] = [(y, y)]
            if y in important_tents_count:
                important_tents_count[y].append((x, x))
            else:
                important_tents_count[y] = [(x, x)]

    significant_x = sorted([x for x in set(x_positions) if important_tents_count[x]])
    significant_y = sorted([y for y in set(y_positions) if important_tents_count[y]])
    sum_weights = collections.defaultdict(int)

    def dfs(x, y, weight):
        for next_x in significant_x:
            if x == next_x or (x in important_tents_count and (y, next_x) in important_tents_count.values()):
                next_y = next_x + (x - next_x) * (y - weight) // abs(x - y - 1)
                if next_y in significant_y:
                    sum_weights[(next_x, next_y)] = max(
                        sum_weights[(next_x, next_y)],
                        weight + dfs(next_x, next_y, y - weight)
                    )

    for x in significant_x:
        for weight in range(1, 10**9 + 1):
            dfs(x, x + 1, weight)

    return sum(sum_weights[x] for x in sum_weights)

