from collections import defaultdict

def check_tournament(a):
    out_deg = defaultdict(int)
    in_deg = defaultdict(int)
    max_out_deg = 0
    max_in_deg = 0

    for i in range(len(a)):
        for j in range(len(a)):
            if a[i] == a[j]:
                continue

            # Bidirectional edges in T
            if i < j:
                if out_deg[j:i+1] & (1 << min(i, j)) > 0:
                    return False, "Duplicate vertex."

            out_deg[j] |= 1 << i
            if out_deg[j] > max_out_deg:
                max_out_deg = out_deg[j]

            # Bidirectional edges in G-neighbor-disjoint T
            if i < j:
                if (in_deg[j] & (1 << min(i, j))) == 0:
                    return False, "No such tournament."
                in_deg[j] &= ~1 << i
                if in_deg[j] == max_out_deg - 1:
                    max_in_deg = 0
            elif i >= j:
                in_deg[i] |= 1 << j

        out_deg[j] ^= 1 << i
        if out_deg[j] > max_out_deg or in_deg[i] > max_in_deg:
            return False, "No such tournament."

    vidtoval = "0" * (1 + max_out_deg) + "1" * (1 + max_in_deg) + "1"

    # Create the tournament graph G-neighbor-disjoint tournament
    num_vertices = max_out_deg + max_in_deg + 2
    tournament = [[0] * num_vertices for _ in range(num_vertices)]

    start = -1
    for i in range(num_vertices):
        if i < max_out_deg:
            value = vidtoval[i]
            if value == "0":
                start += 1
            else:
                tournament[i][start] = 1
        else:
            value = vidtoval[i]
            if value == "0":
                start -= 1
            else:
                tournament[start][i - max_out_deg] = 1

    valid = "YES"
    while num_vertices // 2 > 0:
        count = 0
        total = num_vertices // 2
        left = "0" * total + "1" * total
        while count < total:
            for j in range(len(tournament)):
                if left[j] == '1':
                    if out_deg[j] > max_out_deg or in_deg[j] > max_in_deg:
                        return False, "No such tournament."
                    if in_deg[j] < out_deg[j] - 1:
                        in_deg[j] += 1
                        out_deg[j] -= 1
                        tournament[j][j - max_out_deg] = 0
                        tournament[j][out_deg[j]] = 1
                        break
            else:
                if count + 1 < total:
                    continue
                valid = "NO"
                break
            count += 1
        num_vertices //= 2

    return valid, start+1

