def find_bridge(n, cost):
    for i in range(n):
        for j in range(i+1, n):
            if cost[i][j] < cost[i-1][j-1] and cost[i][j] < cost[i+1][j+1]:
                return cost[i][j]
    return None

def find_bridges(n, cost):
    for i in range(1, n-1):
        if cost[i-1][i-2] + cost[i][i+1] > cost[i-1][i+1] + cost[i][i-2]:
            return find_bridge(n-1, cost[:2]+cost[(n-2):])
    return cost[1:-1]

def find_pairs(n, cost):
    price_matrix = [[float('inf')] * n for _ in range(n)]
    price_matrix[0][0] = cost[0][0]
    for x in range(1, n):
        for y in range(x):
            mincost = float('inf')
            if cost[x-1][y-1] <= cost[x-1][y+1] and cost[x-1][y-1] <= cost[y+1][x-1]:
                mincost = cost[x-1][y-1]
            for m in range(x-1, y):
                if cost[m][y-1] < mincost:
                    mincost = cost[m][y-1]
            for m in range(y+1, x):
                if cost[y+1][m] < mincost:
                    mincost = cost[y+1][m]
            price_matrix[x-1][y-1] = mincost
    return price_matrix

def find_plan(n, cost):
    if n <= 2:
        return [i+1 for i in range(n-1)]

    price_matrix = find_pairs(n, cost)
    if max([max(x) for x in price_matrix]) != min([min(x) for x in price_matrix[1:][:-1]]) + budget:
        return [-1]

    pairs = [-1] * (n-1)
    cost_matrix = [set([x-1, x]) for x in range(1, n)]
    bridges = find_bridges(n, cost_matrix)

    chosen_city = -1
    for i in range(n-1):
        if chosen_city == cost_matrix[i][-1]:
            chosen_city = chosen_city if bridges[i] is None else bridges[i]
        elif cost_matrix[i][-1] in cost_matrix[i][:-1] and chosen_city < 0 or chosen_city < cost_matrix[i][-1] or (cost_matrix[i][-1] < chosen_city and bridges[i] is None or bridges[i] > 0):
            chosen_city = cost_matrix[i][-1]
        else:
            continue

    for i in cost_matrix:
        for j in range(len(i)):
            if chosen_city == i[j]:
                pairs[i.index(i)] = j
                break

    pairs.append(chosen_city)
