```python
from collections import deque

def bfs(graph):
    n = len(graph)
    is_visited = [False] * n
    min_time = [-1] * n
    time = 0
    queue = deque([0])

    while queue:
        vertex = queue.popleft()

        for neighbor in graph[vertex]:
            if not is_visited[neighbor]:
                is_visited[neighbor] = True
                queue.append(neighbor)
                if time == 0:
                    min_time[neighbor] = time
                else:
                    min_time[neighbor] = time - min_time[vertex] + 1
                time += 1

    return min_time

