import sys

def is_well_defended(board, piece_position, strategic_areas):
    """
    Determines if a given area on the board is well defended by the rooks placed on strategic_areas.

    :param board: List of rows, where each row is a list of tuples representing the occupied cells.
    :param piece_position: A tuple (row, column) representing the position of a rook.
    :param strategic_areas: List of strategic areas represented as a list of tuples [x1, y1, x2, y2].
    :return: True if the area is well defended, False otherwise.
    """
    horizontal = absolute_overlap(piece_position, strategic_areas)
    vertical = absolute_overlap(board[piece_position[0]], strategic_areas)
    return horizontal and vertical

def absolute_overlap(board_element, overlapping_elements):
    """
    Helper function to check if a board element overlaps an overlapping element
    in either horizontal or vertical line.

    :param board_element: A tuple representing a cell on the board.
    :param overlapping_elements: List of overlapping elements represented as tuples.
    :return: True if there's an overlap, False otherwise.
    """
    row1, col1 = board_element
    for row2, col2 in overlapping_elements:
        if row2 == row1 or col2 == col1:
            return True
    return False

