def find_longest_increasing_subsequence(s: str) -> int:
    # Initialize the DP array to store the length of the longest increasing subsequence ending at each index
    dp = [1] * len(s)

    # Process the string character by character
    for i in range(1, len(s)):
        for j in range(i):
            if s[i] > s[j]:
                dp[i] = max(dp[i], dp[j] + 1)

