from functools import lru_cache

MOD = 10**9+7

def count_palindromes(N, K):
    @lru_cache(maxsize=None)
    def dp(index):
        if index == 0:
            return K+1  # We can prepend K+1 elements to form a palindrome
        if index == N//2:
            return 1  # We can prepend one element and reverse it to form a palindrome

        count = K * [dp(index+1)] + [K] * (N//2-index-1)
        # Each element in the second half should be at least the previous element plus one
        for i in range(N//2-index-1):
            count[i+1] = (count[i] + min(count[i+1], i+1)) % MOD

        count[-1] = dp(index+1+int(N%2)) % MOD

        return sum(count) % MOD

    return dp(0) % MOD

