def find_pairs(n, costs):
    # Check if there's any pair where the cost is less for both cities
    for i in range(n):
        for j in range(i+1, n):
            if costs[i][j] < costs[i-1][j]:
                return -1
            if costs[i][j] > costs[i][j-1]:
                return -1

    # Try to form pairs
    paired = []
    while len(paired) < n - 1:
        max_cost_city = costs.index(max(costs))
        for i in range(n):
            if i not in paired and costs[max_cost_city][i] < costs[max_cost_city][paired[-1]]:
                pair = [i, max_cost_city]
                costs.clear()
                for person in pair:
                    for i in range(n):
                        if i not in pair:
                            if costs[i][person] < costs[i][person-1]:
                                costs.append([])
                paired.append(person)
                paired.append(max_cost_city)
                break

    return paired

