def count_arrays(n: int, a: list) -> int:
    # XOR of all a_i in non-decreasing array b
    target_xor = a[0] ^ a[1]
    if target_xor not in {0, a[0], a[1] + 1}:
        return 0

    @lru_cache(maxsize=None)
    def dp(i: int, mask: int, lower: int) -> int:
        if i == n + 1:
            return 1 if mask == (1 << (2 * n - 1)) - 1 else 0
        count = 0
        for j in range(n + 1):
            if lower <= mask & a[j] <= mask:
                if mask & (1 << j) == 0:
                    count += dp(i + 1, mask | 1 << j, a[j]) + dp(i + 1, mask, a[j])
        return count

