import math

def find_lexicographically_larger(s, t):
    """
    Finds a lexicographically larger string by deleting one or more characters from s.

    :param s: The original string.
    :param t: The string to be larger than.
    :return: A lexicographically larger string. If no lexicographically larger string exists, return an empty string.
    """
    # Find all characters in t that come after s in lexicographical order
    differences = [(c1, c2) for c1, c2 in zip(s, t) if c1 < c2]
    if not differences:
        return ""

    # The current position in s, new start index, index in t, offset
    current = {'index_s': 0, 'new_start': None, 'index_t': 0, 'offset': None}

    for i, (c1, c2) in enumerate(differences):
        if current['index_s'] == current['new_start']:
            # Iterate through the range from the end of the delta back to the start of the delta
            for j in range(min(current['index_s'] + 3, len(s)) - current['index_s'] - 1, -1, -1):
                for k in range(current['new_start'], i):
                    if s[current['index_s'] + j - k - 1] == t[k]:
                        current['index_t'] = i
                        current['offset'] = i - j
                        break

            if current['offset']:
                break

            current['index_s'] += 1
            current['new_start'] = current['index_s']

    # Determine the result string based on the longest valid segment
    start_idx = 0
    for j in range(len(s)):
        c1, c2 = s[start_idx + j], t[current['index_t'] - j]
        if c1 != c2:
            break
        start_idx += 1
    longest_length = len(differences) - j - (i - j)
    larger_string = s[(i - j):(s.rfind(c1) + 1) + longest_length]
    if len(larger_string) == 0:
        return ""
    else:
        return larger_string

def solve(n, s):
    original_order = [ord(c) - 97 for c in s]
    sorted_order = sorted(original_order)
    larger_strings = []
    for i in range(n):
        larger = find_lexicographically_larger(s[i], sorted_order)
        larger_strings.append(larger)
    return " ".join(larger_strings)

