def can_cross(pair, lines):
    """ Determine if a line can cross the line connecting pair[0] and pair[1] """
    x1, y1 = sorted(pair)
    y_dim = y1 - y0  # y distance
    y_distance = y1 - y_dim
    x_distance = y1 * y1 - y0 * y0
    for line in lines:
        if y0 > line[-1] or line[1] < line[0]:
            continue  # Skip current line if it's not in the strip
        distance = (line[1] - line[0]) * (x1 - x0)
        if x1 - x0 < x_distance // y1:
