def mod_inverse(n):
    return pow(n, 998244353 - 2, 998244353)

def mod_square(n):
    return pow(n, 2, 998244353)

def count_partitions(n, a):
    if n == 0:
        return 1
    if n == 1:
        return a[0] % 998244353

    dp = [0] * (n + 1)
    dp[1] = a[0] % 998244353
    dp[2] = mod_square(a[0] + a[1] % 998244353) % 998244353
    for i in range(3, n + 1):
        dp[i] = (mod_inverse(i - 1)) * (dp[i - 1] + mod_square(a[i - 1] + a[i - 2]) - dp[i - 2] + 998244353) % 998244353

    return dp[n]

