from collections import defaultdict

def minimum_removals(n, a, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    visited = [False] * n
    def dfs(node):
        visited[node] = True
        operations.append(node + 1)  # Offset for 1-indexed lists
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)

    operations = []
    for i in range(n):
        if not visited[i] and a[i] == 2:
            dfs(i)

    return len(operations)

