from collections import Counter

def min_cost_to_make_easy_to_remember():
    n, m = map(int, input().split())
    strings = [list(input()) for _ in range(n)]
    cost_matrix = [list(map(int, input().split())) for _ in range(n)]

    # Initialize DP table where dp[i][j] is the minimum cost to make the first i strings easy to remember ending with j-th string
    dp = [[float('inf')] * 26 for _ in range(n)]

    # First column is always 0 as there is nothing to change initially
    dp[0][ord(strings[0][-1]) - ord('a')] = 0

    for i in range(1, n):
        for j in range(26):
            if cost_matrix[i-1][j] != 0:
                dp[i][j] = min(dp[i][k] + cost_matrix[i-1][j-(ord(strings[i-1][-1]) - ord('a'))] for k in range(26))
            if j == ord(strings[i][-1]) - ord('a'):
                dp[i][j] = 0 if dp[i-1][j] != float('inf') else float('inf')

    return min(dp[-1])

