from math import comb

def falling(n, k):
    if n == 0 or k == 0 or k == n:
        return 0
    res = 1
    i = 0
    while k > 1 and n > i:
        if i < k:
            res = (res * (n - i + 1)) % 998244353
        i += 1
        n -= 1
    return res % 998244353

def mod_fac(n) -> int:
    dp = [1] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = (2 * dp[i - 1]) % 998244353
        dp[i] = dp[i] * falling(n - 1, (i - 1)) % 998244353
    return dp[n]

mod_inv = mod_fac(998244353 - 2)

def solve(a):
    ans = mod_fac(n - 1)
    for i in range(n):
        if a[i] == 0:
            ans = (ans * 2) % 998244353
    ob = mod_inv
    ans = ans * mod_fac(n - 1) % 998244353
    for i in range(n - 1):
        if a[i] == a[i + 1]:
            ans = (ans * 2) % 998244353
    return ans

