def is_possible(scores):
    def min_tournament_scores(scores):
        dp = [0] * len(scores)
        for i in range(1, len(scores)):
            for j in range(i):
                d = max(scores[i], scores[j])
                while scores[j] > 0:
                    if scores[i] > scores[j]:
                        scores[i] -= 1
                        dp[i] += 1
                    else:
                        scores[j] -= 1
                        dp[-dp[i]] += 1
                    if dp[i] >= dp[j] and dp[j] == dp[-dp[i]]:
                        dp[-dp[j]] = -1
                        break
                    if dp[j] == 0:
                        return d
        return dp

    if len(scores) % 2 != 0:
        return "=("
    scores.sort()
    d = max(scores)
    n = int(d * (d - 1) / 2)
    count = {}
    for i in scores:
        if i not in count:
            count[i] = 1
        else:
            count[i] += 1
    min_t = min_tournament_scores(scores)
    if min_t < 0:
        return "=("
    n -= int(min_t / 2) - 1
    return str(n), '\n'.join([' '.join(['0' * i] * n) for i in range(n)])
